mapper.select:
SELECT 
FROM t_ai_conversation
WHERE conversation_no = #{conversationNo}
  AND user_id = #{userId}

SELECT 
FROM t_ai_conversation
WHERE user_id = #{userId}
  AND status = 'ACTIVE'
  AND (
      (#{contextObjectType} IS NULL AND context_object_type IS NULL)
      OR context_object_type = #{contextObjectType}
  )
  AND (
      (#{contextObjectId} IS NULL AND context_object_id IS NULL)
      OR context_object_id = #{contextObjectId}
  )
ORDER BY last_message_time DESC, create_time DESC, id DESC
LIMIT 1

mapper.update:
UPDATE t_ai_conversation
SET title = #{title},
    edit_time = #{editTime},
    edit_by = #{editBy}
WHERE id = #{id}

UPDATE t_ai_conversation
SET status = 'ARCHIVED',
    edit_time = #{editTime},
    edit_by = #{editBy}
WHERE id = #{id}
